{"summary": "Integration test for GET /api/version.", "files": [{"path": "tests/UrlShortener.Tests/Api/VersionEndpointTests.cs", "content": "using System.Net;
using System.Net.Http.Json;

namespace UrlShortener.Tests.Api;

public sealed class VersionEndpointTests : IAsyncLifetime
{
    private readonly ShortenerApiFactory _factory = new();

    public Task InitializeAsync() => _factory.InitializeDatabaseAsync();

    public async Task DisposeAsync() => await _factory.DisposeAsync();

    [Fact]
    public async Task Version_returns_200_with_a_non_empty_version()
    {
        using var client = _factory.CreateClient();

        var response = await client.GetAsync("/api/version");

        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
        var body = await response.Content.ReadFromJsonAsync<VersionDto>();
        Assert.False(string.IsNullOrWhiteSpace(body?.Version));
    }

    private sealed record VersionDto(string Version);
}
